// dropNonReadOnlyTools removes every tool not annotated readOnlyHint=true.
// A tool with no annotation fails closed.
func dropNonReadOnlyTools(s *server.MCPServer) {
	var drop []string
	for name, entry := range s.ListTools() {
		if hint := entry.Tool.Annotations.ReadOnlyHint; hint == nil || !*hint {
			drop = append(drop, name)
		}
	}
	s.DeleteTools(drop...)
}

type mcpParamBinding struct {
	PublicName string
	WireName   string
	Location   string
	BodyPath   []string
	Format     string
}

type mcpPageConfig struct {
	CursorParam          string
	NextCursorPath       string
	HasMoreField         string
	ContinuationInput    string
	CursorInBody         bool
	ExternalContinuation bool
	BodyPath             []string
}

func formatMCPParamValue(v any) string {
	switch tv := v.(type) {
	case string:
		return tv
	case bool:
		return strconv.FormatBool(tv)
	case float64:
		if math.IsNaN(tv) || math.IsInf(tv, 0) {
			return strconv.FormatFloat(tv, 'f', -1, 64)
		}
		if math.Trunc(tv) == tv && math.Abs(tv) < 1e15 {
			return strconv.FormatInt(int64(tv), 10)
		}
		return strconv.FormatFloat(tv, 'f', -1, 64)
	case float32:
		f := float64(tv)
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return strconv.FormatFloat(f, 'f', -1, 32)
		}
		if math.Trunc(f) == f && math.Abs(f) < 1e15 {
			return strconv.FormatInt(int64(f), 10)
		}
		return strconv.FormatFloat(f, 'f', -1, 32)
	default:
		// Composite values (a native []any / map[string]any from an array or
		// object param) reach this path when bound to a query or path slot;
		// JSON-encode them so the wire value is valid JSON rather than Go's
		// "[a b c]" / "map[...]" rendering. Body params never come through
		// here — they are stored natively in bodyArgs and marshalled there.
		if b, err := json.Marshal(v); err == nil {
			return string(b)
		}
		return fmt.Sprintf("%v", v)
	}
}

func mcpPathValue(v any) string {
	return cliutil.EscapePathParam(formatMCPParamValue(v))
}
func setNestedBodyArg(body map[string]any, path []string, value any) {
	if len(path) == 0 {
		return
	}
	if len(path) == 1 {
		body[path[0]] = value
		return
	}
	current := body
	for _, key := range path[:len(path)-1] {
		next, ok := current[key].(map[string]any)
		if !ok {
			next = map[string]any{}
			current[key] = next
		}
		current = next
	}
	current[path[len(path)-1]] = value
}

func nestedBodyString(body map[string]any, path []string) (string, bool) {
	if len(path) == 0 {
		return "", false
	}
	current := any(body)
	for _, key := range path {
		obj, ok := current.(map[string]any)
		if !ok {
			return "", false
		}
		next, ok := obj[key]
		if !ok {
			return "", false
		}
		current = next
	}
	s, ok := current.(string)
	return s, ok
}

func deleteNestedBodyArg(body map[string]any, path []string) {
	if len(path) == 0 {
		return
	}
	if len(path) == 1 {
		delete(body, path[0])
		return
	}
	current := body
	for _, key := range path[:len(path)-1] {
		next, ok := current[key].(map[string]any)
		if !ok {
			return
		}
		current = next
	}
	delete(current, path[len(path)-1])
}
func coerceMCPBodyValue(binding mcpParamBinding, value any) (any, error) {
	if binding.Format != "json_or_scalar" {
		return value, nil
	}
	s, ok := value.(string)
	if !ok || !looksLikeMCPJSONComposite(s) {
		return value, nil
	}
	var parsed any
	if err := json.Unmarshal([]byte(s), &parsed); err != nil {
		return nil, fmt.Errorf("parsing %s JSON: %w", binding.PublicName, err)
	}
	return parsed, nil
}

func looksLikeMCPJSONComposite(input string) bool {
	input = strings.TrimSpace(input)
	return strings.HasPrefix(input, "{") || strings.HasPrefix(input, "[")
}

// makeAPIHandler creates a generic MCP tool handler for an API endpoint.
func makeAPIHandler(method, pathTemplate string, readOnly bool, binaryResponse bool, headerOverrides map[string]string, pageConfig mcpPageConfig, bindings []mcpParamBinding, positionalParams []string) server.ToolHandlerFunc {
	return func(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
		c, platformSession, err := newMCPClient(ctx)
		if err != nil {
			return mcpToolError(err.Error()), nil
		}
		if platformSession != nil {
			defer platformSession.ZeroCredentials()
		}

		// mcp-go v0.47+ made CallToolParams.Arguments an `any` to support
		// non-map payloads; GetArguments() returns the map[string]any shape
		// we rely on here (or an empty map when the payload is something else).
		args := req.GetArguments()
		if err := cli.AdoptMCPOutputSemantics(platformSession, args); err != nil {
			return mcpToolError(err.Error()), nil
		}

		// positionalParams mixes real URL path params with CLI positional
		// args that map to query params (e.g. `search <query>` -> ?query=);
		// the placeholder check below disambiguates them at runtime.
		path := pathTemplate
		knownArgs := make(map[string]bool, len(bindings))
		pathParams := make(map[string]bool, len(positionalParams))
		params := make(map[string]string)
		bodyArgs := make(map[string]any)
		mcpCursor := ""
		requestCursor := ""
		if pageConfig.CursorParam != "" || pageConfig.ExternalContinuation || pageConfig.ContinuationInput != "" {
			knownArgs["cursor"] = true
			if v, ok := args["cursor"]; ok {
				s, ok := v.(string)
				if !ok {
					return mcpToolError("cursor must be an opaque string returned by a previous MCP response"), nil
				}
				if s != "" {
					upstreamCursor, err := bound.UpstreamCursor(s)
					if err == nil {
						mcpCursor = s
						requestCursor = upstreamCursor
						if upstreamCursor != "" && pageConfig.CursorParam != "" && !pageConfig.CursorInBody {
							params[pageConfig.CursorParam] = upstreamCursor
						}
					} else if !strings.EqualFold(method, "GET") && pageConfig.CursorParam != "" {
						requestCursor = s
						if !pageConfig.CursorInBody {
							params[pageConfig.CursorParam] = s
						}
					} else {
						return mcpToolError(err.Error()), nil
					}
				}
			}
		}
		var headers map[string]string
		if len(headerOverrides) > 0 {
			headers = make(map[string]string, len(headerOverrides)+1)
			for k, v := range headerOverrides {
				headers[k] = v
			}
		}
		if binaryResponse {
			if headers == nil {
				headers = map[string]string{}
			}
			headers[client.BinaryResponseHeader] = "true"
		}
		// bodyJSONOverride holds an opaque body for endpoints whose request
		// schema is a oneOf/anyOf and was wired with a single body_json input.
		// When set, it replaces the bodyArgs map for POST/PUT/PATCH.
		var bodyJSONOverride json.RawMessage
		for _, binding := range bindings {
			knownArgs[binding.PublicName] = true
			v, ok := args[binding.PublicName]
			if !ok {
				continue
			}
			switch binding.Location {
			case "path":
				placeholder := "{" + binding.WireName + "}"
				pathParams[binding.PublicName] = true
				path = strings.Replace(path, placeholder, mcpPathValue(v), 1)
			case "header":
				if headers == nil {
					headers = map[string]string{}
				}
				headers[binding.WireName] = formatMCPParamValue(v)
			case "body":
				bodyValue, err := coerceMCPBodyValue(binding, v)
				if err != nil {
					return mcpToolError(err.Error()), nil
				}
				if len(binding.BodyPath) > 0 {
					setNestedBodyArg(bodyArgs, binding.BodyPath, bodyValue)
				} else {
					bodyArgs[binding.WireName] = bodyValue
				}
			case "body_json":
				if s, ok := v.(string); ok && s != "" {
					var parsed any
					if err := json.Unmarshal([]byte(s), &parsed); err != nil {
						return mcpToolError("body_json must be a valid JSON object: " + err.Error()), nil
					}
					if _, isMap := parsed.(map[string]any); !isMap {
						return mcpToolError(fmt.Sprintf("body_json must be a JSON object, got JSON %T", parsed)), nil
					}
					bodyJSONOverride = json.RawMessage(s)
				}
			default:
				params[binding.WireName] = formatMCPParamValue(v)
			}
		}
		for _, p := range positionalParams {
			placeholder := "{" + p + "}"
			if !strings.Contains(pathTemplate, placeholder) {
				continue
			}
			pathParams[p] = true
			if v, ok := args[p]; ok {
				path = strings.Replace(path, placeholder, mcpPathValue(v), 1)
			}
		}

		if err := rejectUndeclaredMCPArgs(args, knownArgs, pathParams); err != nil {
			return mcpToolError(err.Error()), nil
		}

		// The public cursor argument is either an opaque MCP cursor or, on a
		// read-only non-GET, the API cursor itself. Replay must send the API
		// cursor, never the opaque blob, or the next slice skips entries.
		// Query and form fields carry that cursor the same way the JSON body does.
		if pageConfig.CursorInBody && pageConfig.CursorParam != "" {
			if len(pageConfig.BodyPath) > 0 {
				if mcpCursor != "" {
					if requestCursor != "" {
						setNestedBodyArg(bodyArgs, pageConfig.BodyPath, requestCursor)
					} else {
						deleteNestedBodyArg(bodyArgs, pageConfig.BodyPath)
					}
				} else if s, ok := nestedBodyString(bodyArgs, pageConfig.BodyPath); ok {
					requestCursor = s
				}
			} else if mcpCursor != "" {
				if requestCursor != "" {
					bodyArgs[pageConfig.CursorParam] = requestCursor
				} else {
					delete(bodyArgs, pageConfig.CursorParam)
				}
			} else if s, ok := bodyArgs[pageConfig.CursorParam].(string); ok {
				requestCursor = s
			}
		}
		if !strings.EqualFold(method, "GET") && !pageConfig.CursorInBody && pageConfig.CursorParam != "" {
			if mcpCursor != "" {
				if requestCursor != "" {
					params[pageConfig.CursorParam] = requestCursor
				} else {
					delete(params, pageConfig.CursorParam)
				}
			} else if s, ok := params[pageConfig.CursorParam]; ok && s != "" {
				requestCursor = s
			}
		}

		var data json.RawMessage
		switch method {
		case "GET":
			if len(headers) > 0 {
				if readOnly {
					data, err = c.GetWithHeaders(ctx, path, params, headers)
				} else {
					data, err = c.GetMutatingWithHeaders(ctx, path, params, headers)
				}
				break
			}
			if readOnly {
				data, err = c.Get(ctx, path, params)
			} else {
				data, err = c.GetMutating(ctx, path, params)
			}
		case "POST":
			if len(bodyJSONOverride) > 0 {
				if len(headers) > 0 {
					if readOnly {
						data, _, err = c.PostQueryWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					} else {
						data, _, err = c.PostWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					}
					break
				}
				if readOnly {
					data, _, err = c.PostQueryWithParams(ctx, path, params, bodyJSONOverride)
				} else {
					data, _, err = c.PostWithParams(ctx, path, params, bodyJSONOverride)
				}
				break
			}
			if len(headers) > 0 {
				if readOnly {
					data, _, err = c.PostQueryWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				} else {
					data, _, err = c.PostWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				}
				break
			}
			if readOnly {
				data, _, err = c.PostQueryWithParams(ctx, path, params, bodyArgs)
			} else {
				data, _, err = c.PostWithParams(ctx, path, params, bodyArgs)
			}
		case "PUT":
			if len(bodyJSONOverride) > 0 {
				if len(headers) > 0 {
					if readOnly {
						data, _, err = c.PutQueryWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					} else {
						data, _, err = c.PutWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					}
					break
				}
				if readOnly {
					data, _, err = c.PutQueryWithParams(ctx, path, params, bodyJSONOverride)
				} else {
					data, _, err = c.PutWithParams(ctx, path, params, bodyJSONOverride)
				}
				break
			}
			if len(headers) > 0 {
				if readOnly {
					data, _, err = c.PutQueryWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				} else {
					data, _, err = c.PutWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				}
				break
			}
			if readOnly {
				data, _, err = c.PutQueryWithParams(ctx, path, params, bodyArgs)
			} else {
				data, _, err = c.PutWithParams(ctx, path, params, bodyArgs)
			}
		case "PATCH":
			if len(bodyJSONOverride) > 0 {
				if len(headers) > 0 {
					if readOnly {
						data, _, err = c.PatchQueryWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					} else {
						data, _, err = c.PatchWithParamsAndHeaders(ctx, path, params, bodyJSONOverride, headers)
					}
					break
				}
				if readOnly {
					data, _, err = c.PatchQueryWithParams(ctx, path, params, bodyJSONOverride)
				} else {
					data, _, err = c.PatchWithParams(ctx, path, params, bodyJSONOverride)
				}
				break
			}
			if len(headers) > 0 {
				if readOnly {
					data, _, err = c.PatchQueryWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				} else {
					data, _, err = c.PatchWithParamsAndHeaders(ctx, path, params, bodyArgs, headers)
				}
				break
			}
			if readOnly {
				data, _, err = c.PatchQueryWithParams(ctx, path, params, bodyArgs)
			} else {
				data, _, err = c.PatchWithParams(ctx, path, params, bodyArgs)
			}
		case "DELETE":
			if len(headers) > 0 {
				data, _, err = c.DeleteWithParamsAndHeaders(ctx, path, params, headers)
				break
			}
			data, _, err = c.DeleteWithParams(ctx, path, params)
		default:
			return mcpToolError("unsupported method: " + method), nil
		}

		if err != nil {
			msg := err.Error()
			switch {
			case strings.Contains(msg, "HTTP 409"):
				return mcpToolTextWithPlatform("already exists (no-op)", platformSession), nil
			case strings.Contains(msg, "HTTP 400") && cliutil.LooksLikeAuthError(msg):
				return mcpToolError("authentication error: " + cliutil.SanitizeErrorBody(msg) +
					"\nhint: the API rejected the request — this usually means auth is missing or invalid." +
					"\n      " + "Set it with: echo \"$TOKEN\" | cloro-pp-cli auth set-token or " + cliutil.EnvAssignHint(true, "CLORO_API_KEY", "your-token-here") +
					"\n      Get a key at: https://dashboard.cloro.dev/api-keys?utm_source=printing-press-library&utm_medium=byok" +
					"\n      Run 'cloro-pp-cli doctor' to check auth status."), nil
			case strings.Contains(msg, "HTTP 401"):
				return mcpToolError("authentication failed: " + cliutil.SanitizeErrorBody(msg) +
					"\nhint: check your token." +
					"\n      " + "Set it with: echo \"$TOKEN\" | cloro-pp-cli auth set-token or " + cliutil.EnvAssignHint(true, "CLORO_API_KEY", "your-token-here") +
					"\n      Get a key at: https://dashboard.cloro.dev/api-keys?utm_source=printing-press-library&utm_medium=byok" +
					"\n      Run 'cloro-pp-cli doctor' to check auth status."), nil
			case strings.Contains(msg, "HTTP 403"):
				return mcpToolError("permission denied: " + cliutil.SanitizeErrorBody(msg) +
					"\nhint: your credentials are valid but lack access to this resource. Check that they have the required permissions and match the API's expected auth scheme." +
					"\n      " + "Set it with: echo \"$TOKEN\" | cloro-pp-cli auth set-token or " + cliutil.EnvAssignHint(true, "CLORO_API_KEY", "your-token-here") +
					"\n      Get a key at: https://dashboard.cloro.dev/api-keys?utm_source=printing-press-library&utm_medium=byok" +
					"\n      Run 'cloro-pp-cli doctor' to check auth status."), nil
			case strings.Contains(msg, "HTTP 404"):
				if method == "DELETE" {
					return mcpToolTextWithPlatform("already deleted (no-op)", platformSession), nil
				}
				return mcpToolError("not found: " + msg), nil
			case strings.Contains(msg, "HTTP 429"):
				return mcpToolError("rate limited: " + msg), nil
			default:
				return mcpToolError(msg), nil
			}
		}

		if binaryResponse {
			encoded := base64.StdEncoding.EncodeToString(data)
			out, err := json.Marshal(map[string]any{
				"content_encoding": "base64",
				"data_base64":      encoded,
				"byte_count":       len(data),
			})
			if err != nil {
				return mcpToolError(fmt.Sprintf("encoding binary result: %v", err)), nil
			}
			if len(out) > bound.MaxBytes {
				return mcpToolError(fmt.Sprintf("binary response is too large for MCP text output: %d response bytes encode to %d base64 bytes and %d MCP result bytes, exceeding the %d byte budget. Use the companion CLI command with --output <file> to save the payload locally.", len(data), len(encoded), len(out), bound.MaxBytes)), nil
			}
			result := string(out)
			if platformSession != nil {
				result = bound.WithMetadata(result, platformSession.OutputMetadata())
			}
			return mcplib.NewToolResultText(result), nil
		}
		if pageConfig.CursorParam != "" || pageConfig.NextCursorPath != "" || pageConfig.ExternalContinuation {
			return mcpToolPageResultTextWithPlatform(method, data, pageConfig, mcpCursor, requestCursor, readOnly, platformSession), nil
		}
		return mcpToolResultTextWithPlatform(method, data, readOnly, platformSession), nil
	}
}

func mcpToolResultText(method string, data json.RawMessage) *mcplib.CallToolResult {
	return mcpToolResultTextWithPlatform(method, data, false, nil)
}

func mcpToolTextWithPlatform(result string, platformSession *platform.Session) *mcplib.CallToolResult {
	if platformSession != nil {
		result = bound.WithMetadata(result, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(result)
}

func mcpToolResultTextWithPlatform(method string, data json.RawMessage, readOnly bool, platformSession *platform.Session) *mcplib.CallToolResult {
	result := bound.EndpointPageResponse(method, data, bound.PageOptions{ReadOnly: readOnly})
	return mcpToolTextWithPlatform(result, platformSession)
}

// mcpToolError keeps provider-controlled typed endpoint errors within the MCP
// text-result budget just like successful endpoint results.
func mcpToolError(message string) *mcplib.CallToolResult {
	return mcplib.NewToolResultError(bound.Text(message))
}

// Reserved transport arguments are accepted on every endpoint tool. They are
// not request fields, so an unused one is ignored instead of copied onto the
// wire. Declared bindings with these names still flow through knownArgs.
func mcpReservedArg(name string) bool {
	switch name {
	case "cursor", "body_json", "body_base64", "content_type":
		return true
	default:
		return false
	}
}

func rejectUndeclaredMCPArgs(args map[string]any, knownArgs, pathParams map[string]bool) error {
	var unknown []string
	for name := range args {
		if pathParams[name] || knownArgs[name] || mcpReservedArg(name) {
			continue
		}
		unknown = append(unknown, name)
	}
	if len(unknown) == 0 {
		return nil
	}
	sort.Strings(unknown)
	candidates := mcpArgCandidates(knownArgs, pathParams)
	parts := make([]string, len(unknown))
	for i, name := range unknown {
		parts[i] = formatUnknownMCPArg(name, suggestMCPArg(name, candidates))
	}
	return fmt.Errorf("%s", strings.Join(parts, "; "))
}

func mcpArgCandidates(knownArgs, pathParams map[string]bool) []string {
	names := make([]string, 0, len(knownArgs)+len(pathParams))
	seen := make(map[string]struct{}, len(knownArgs)+len(pathParams))
	for name := range knownArgs {
		if _, ok := seen[name]; ok {
			continue
		}
		seen[name] = struct{}{}
		names = append(names, name)
	}
	for name := range pathParams {
		if _, ok := seen[name]; ok {
			continue
		}
		seen[name] = struct{}{}
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func formatUnknownMCPArg(name, suggestion string) string {
	if suggestion == "" {
		return fmt.Sprintf("unknown argument %q", name)
	}
	return fmt.Sprintf("unknown argument %q (did you mean %q?)", name, suggestion)
}

func suggestMCPArg(name string, candidates []string) string {
	folded := mcpArgFold(name)
	stripped := mcpArgStrip(folded)
	best := ""
	bestDist := 0
	ambiguous := false
	consider := func(cand string, dist int) {
		if best == "" || dist < bestDist {
			best = cand
			bestDist = dist
			ambiguous = false
			return
		}
		if dist == bestDist && cand != best {
			ambiguous = true
		}
	}
	for _, cand := range candidates {
		if cand == "" || cand == name {
			continue
		}
		cf := mcpArgFold(cand)
		if cf == folded {
			consider(cand, 0)
			continue
		}
		if stripped != "" && mcpArgStrip(cf) == stripped {
			consider(cand, 0)
			continue
		}
		dist := runeLevenshtein(folded, cf)
		if mcpArgDistanceOK(folded, cf, dist) {
			consider(cand, dist)
		}
	}
	if ambiguous {
		return ""
	}
	return best
}

func mcpArgFold(name string) string {
	return strings.ReplaceAll(strings.ToLower(name), "-", "_")
}

func mcpArgStrip(folded string) string {
	return strings.ReplaceAll(folded, "_", "")
}

func mcpArgDistanceOK(a, b string, dist int) bool {
	if dist <= 0 {
		return false
	}
	la, lb := len([]rune(a)), len([]rune(b))
	if la < 3 || lb < 3 {
		return false
	}
	if la >= 5 && lb >= 5 {
		return dist <= 2
	}
	return dist <= 1
}

func runeLevenshtein(a, b string) int {
	ar, br := []rune(a), []rune(b)
	if len(ar) == 0 {
		return len(br)
	}
	if len(br) == 0 {
		return len(ar)
	}
	prev := make([]int, len(br)+1)
	cur := make([]int, len(br)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ar); i++ {
		cur[0] = i
		for j := 1; j <= len(br); j++ {
			cost := 1
			if ar[i-1] == br[j-1] {
				cost = 0
			}
			del, ins, sub := prev[j]+1, cur[j-1]+1, prev[j-1]+cost
			cur[j] = del
			if ins < cur[j] {
				cur[j] = ins
			}
			if sub < cur[j] {
				cur[j] = sub
			}
		}
		prev, cur = cur, prev
	}
	return prev[len(br)]
}

func mcpToolPageResultText(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor string) *mcplib.CallToolResult {
	return mcpToolPageResultTextWithPlatform(method, data, pageConfig, cursor, "", false, nil)
}

func mcpToolPageResultTextWithPlatform(method string, data json.RawMessage, pageConfig mcpPageConfig, cursor, requestCursor string, readOnly bool, platformSession *platform.Session) *mcplib.CallToolResult {
	result := bound.EndpointPageResponse(method, data, bound.PageOptions{
		Cursor:               cursor,
		CursorParam:          pageConfig.CursorParam,
		NextCursorPath:       pageConfig.NextCursorPath,
		HasMoreField:         pageConfig.HasMoreField,
		RequestCursor:        requestCursor,
		ReadOnly:             readOnly,
		ExternalContinuation: pageConfig.ExternalContinuation,
	})
	if platformSession != nil {
		result = bound.WithMetadata(result, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(result)
}

func newMCPClient(ctx context.Context) (*client.Client, *platform.Session, error) {
	cfg, err := newMCPConfig()
	if err != nil {
		return nil, nil, err
	}
	return newMCPClientFromConfig(ctx, cfg)
}

func newMCPConfig() (*config.Config, error) {
	cfg, err := config.Load("")
	if err != nil {
		return nil, fmt.Errorf("loading config: %w", err)
	}
	return cfg, nil
}

func newMCPClientFromConfig(ctx context.Context, cfg *config.Config) (*client.Client, *platform.Session, error) {
	c := client.New(cfg, 60*time.Second, defaultMCPRateLimit)
	if tlsErr := c.TLSConfigError(); tlsErr != nil {
		return nil, nil, tlsErr
	}
	// Agents calling through MCP need fresh data every call. The on-disk
	// response cache survives across MCP server invocations, so a
	// DELETE/PATCH followed by a GET would otherwise return the
	// pre-mutation snapshot for up to the cache TTL. The interactive CLI
	// constructs its own client and is unaffected.
	c.NoCache = true
	session, err := cli.BindMCPClient(ctx, c)
	if err != nil {
		return nil, nil, err
	}
	if err := cli.ApplyClientHooks(c); err != nil {
		if session != nil {
			session.ZeroCredentials()
		}
		return nil, nil, fmt.Errorf("initializing MCP client: %w", err)
	}
	return c, session, nil
}

func mcpDBPath() (string, error) {
	return cli.MCPStorePath()
}

type mcpStoreStatusKind string

const (
	mcpStoreStatusEmpty   mcpStoreStatusKind = "empty"
	mcpStoreStatusPartial mcpStoreStatusKind = "partial"
	mcpStoreStatusReady   mcpStoreStatusKind = "ready"
)

func openMCPReadOnlyStore(path string) (*store.Store, *mcplib.CallToolResult) {
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return nil, mcplib.NewToolResultError(mcpMissingStoreMessage(path))
		}
		return nil, mcplib.NewToolResultError(fmt.Sprintf("checking local data store %s: %v", path, err))
	}
	db, err := store.OpenReadOnly(path)
	if err != nil {
		return nil, mcplib.NewToolResultError(fmt.Sprintf("opening local data store %s: %v. Run cloro-pp-cli sync --resources states to refresh the store, or use live endpoint MCP tools for unsynced data.", path, err))
	}
	return db, nil
}

func mcpMissingStoreMessage(path string) string {
	return fmt.Sprintf("No local data store found at %s. Run cloro-pp-cli sync --resources states before using MCP search/sql, or use live endpoint MCP tools for unsynced data.", path)
}

func mcpStoreStatus(db *store.Store) (mcpStoreStatusKind, error) {
	status, err := db.Status()
	if err != nil {
		return "", err
	}
	var checkpoints, completed int
	err = db.DB().QueryRow(`SELECT COUNT(*), COALESCE(SUM(CASE WHEN last_attempt_complete = 1 THEN 1 ELSE 0 END), 0) FROM sync_state`).Scan(&checkpoints, &completed)
	if err != nil && strings.Contains(strings.ToLower(err.Error()), "no such column: last_attempt_complete") {
		// Read-only stores have not run the conservative completion migration.
		// Legacy timestamps were also written by partial walks, so prove nothing.
		err = db.DB().QueryRow(`SELECT COUNT(*), 0 FROM sync_state`).Scan(&checkpoints, &completed)
	}
	if err != nil {
		msg := strings.ToLower(err.Error())
		if strings.Contains(msg, "no such table") || strings.Contains(msg, "no such column") {
			if len(status) > 0 {
				return mcpStoreStatusReady, nil
			}
			return mcpStoreStatusEmpty, nil
		}
		return "", err
	}
	if checkpoints > 0 {
		if completed == checkpoints {
			return mcpStoreStatusReady, nil
		}
		return mcpStoreStatusPartial, nil
	}
	if len(status) > 0 {
		return mcpStoreStatusReady, nil
	}
	return mcpStoreStatusEmpty, nil
}

func mcpEmptyStoreNextStep() string {
	return "Run cloro-pp-cli sync --resources states to populate the local SQLite store before using MCP search/sql."
}

func mcpPartialStoreNextStep() string {
	return "The latest sync attempt is incomplete. Resume or rerun cloro-pp-cli sync --resources states before treating local search/sql results as a complete snapshot."
}

func handleSearch(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query, ok := args["query"].(string)
	if !ok || query == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}

	limit := 25
	limitCapped := false
	if v, ok := args["limit"].(float64); ok && v > 0 {
		if v > float64(bound.MaxItems) {
			limit = bound.MaxItems
			limitCapped = true
		} else {
			limit = int(v)
		}
	}

	path, err := mcpDBPath()
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("resolving database: %v", err)), nil
	}
	db, toolErr := openMCPReadOnlyStore(path)
	if toolErr != nil {
		return toolErr, nil
	}
	defer db.Close()

	queryCtx, cancel := bound.WithSQLQueryDeadline(ctx)
	defer cancel()
	results, err := db.SearchContext(queryCtx, query, limit)
	if err != nil {
		if queryCtx.Err() != nil {
			return mcplib.NewToolResultError(fmt.Sprintf("search cancelled: %v. MCP search queries are bounded to %s.", queryCtx.Err(), bound.SQLQueryTimeout)), nil
		}
		return mcplib.NewToolResultError(fmt.Sprintf("search failed: %v", err)), nil
	}
	storeStatus, err := mcpStoreStatus(db)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("reading store status: %v", err)), nil
	}

	return toolResultJSON(mcpSearchEnvelope(results, storeStatus, limitCapped))
}

func mcpSearchEnvelope(results []json.RawMessage, storeStatus mcpStoreStatusKind, limitCapped bool) map[string]any {
	if results == nil {
		results = []json.RawMessage{}
	}
	out := map[string]any{
		"count":        len(results),
		"results":      results,
		"store_status": storeStatus,
		"resumable":    false,
	}
	if limitCapped {
		out["limit_capped"] = true
	}
	if storeStatus == mcpStoreStatusPartial {
		out["warning"] = "Local data may be incomplete because the latest sync attempt did not finish."
		out["next_step"] = mcpPartialStoreNextStep()
	} else if len(results) == 0 {
		if storeStatus == mcpStoreStatusEmpty {
			out["next_step"] = mcpEmptyStoreNextStep()
		} else {
			out["next_step"] = "No local search matches. Try a broader query, a lower-specificity FTS expression, or sync again if data may be stale."
		}
	}
	return out
}

// validateReadOnlyQuery gates the MCP sql tool. The agent contract advertised
// to the host is ReadOnlyHintAnnotation(true); a false annotation on a
// mutating tool lets MCP hosts auto-approve writes and is treated as a real
// bug per the project's agent-native security model.
//
// The gate rejects multi-statement input, then applies an allowlist (SELECT or
// WITH only) AFTER stripping the leading whitespace, line comments, block
// comments, and semicolons that SQLite itself ignores before parsing. A naive
// HasPrefix check on a keyword blocklist is bypassable by prefixing the
// dangerous statement with "/* x */" or "-- x\n"; a naive leading-keyword
// allowlist is bypassable by appending "; ATTACH DATABASE ...". Combined with
// the empirical fact that modernc.org/sqlite's mode=ro does NOT block VACUUM
// INTO (writes a snapshot to a new file) or ATTACH DATABASE (opens a separate
// writable handle), either bypass produces silent exfiltration to an
// attacker-chosen path.
//
// SELECT and WITH are the only allowed leading keywords. WITH supports
// SELECT-form CTEs; CTE-wrapped writes ("WITH x AS (...) INSERT ...") are
// caught by OpenReadOnly's mode=ro one layer down. PRAGMA, ATTACH, VACUUM,
// and every other DDL/DML keyword fail at this gate before reaching SQLite.
func validateReadOnlyQuery(query string) error {
	stripped := stripLeadingSQLNoise(query)
	if hasTrailingSQLStatement(stripped) {
		return fmt.Errorf("only a single SELECT or WITH statement is allowed")
	}
	upper := strings.ToUpper(stripped)
	if !strings.HasPrefix(upper, "SELECT") && !strings.HasPrefix(upper, "WITH") {
		return fmt.Errorf("only SELECT queries are allowed")
	}
	return nil
}

// stripLeadingSQLNoise removes leading whitespace, SQL line comments
// (-- to end of line), block comments (/* ... */), and statement
// separators (;) from query. SQLite skips these before parsing the first
// keyword, so a security gate that does not strip them mismatches what the
// driver actually executes.
func stripLeadingSQLNoise(query string) string {
	for {
		query = strings.TrimLeft(query, " \t\r\n;")
		switch {
		case strings.HasPrefix(query, "--"):
			if idx := strings.IndexByte(query, '\n'); idx >= 0 {
				query = query[idx+1:]
				continue
			}
			return ""
		case strings.HasPrefix(query, "/*"):
			if idx := strings.Index(query[2:], "*/"); idx >= 0 {
				query = query[2+idx+2:]
				continue
			}
			return ""
		default:
			return query
		}
	}
}

// hasTrailingSQLStatement reports whether query contains a statement
// terminator followed by more executable SQL. A trailing semicolon is allowed;
// a second statement is not. Semicolons inside string literals, quoted
// identifiers, bracket identifiers, and comments are ignored to match SQLite's
// parser shape closely enough for this security gate.
func hasTrailingSQLStatement(query string) bool {
	inSingle := false
	inDouble := false
	inBacktick := false
	inBracket := false
	inLineComment := false
	inBlockComment := false

	for i := 0; i < len(query); i++ {
		ch := query[i]
		next := byte(0)
		if i+1 < len(query) {
			next = query[i+1]
		}

		switch {
		case inLineComment:
			if ch == '\n' {
				inLineComment = false
			}
			continue
		case inBlockComment:
			if ch == '*' && next == '/' {
				inBlockComment = false
				i++
			}
			continue
		case inSingle:
			if ch == '\'' {
				if next == '\'' {
					i++
					continue
				}
				inSingle = false
			}
			continue
		case inDouble:
			if ch == '"' {
				if next == '"' {
					i++
					continue
				}
				inDouble = false
			}
			continue
		case inBacktick:
			if ch == '`' {
				if next == '`' {
					i++
					continue
				}
				inBacktick = false
			}
			continue
		case inBracket:
			if ch == ']' {
				inBracket = false
			}
			continue
		}

		switch {
		case ch == '-' && next == '-':
			inLineComment = true
			i++
		case ch == '/' && next == '*':
			inBlockComment = true
			i++
		case ch == '\'':
			inSingle = true
		case ch == '"':
			inDouble = true
		case ch == '`':
			inBacktick = true
		case ch == '[':
			inBracket = true
		case ch == ';':
			if stripLeadingSQLNoise(query[i+1:]) != "" {
				return true
			}
			return false
		}
	}
	return false
}

const mcpSQLMaxValueBytes = 4 << 20

func handleSQL(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query, ok := args["query"].(string)
	if !ok || query == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}

	if err := validateReadOnlyQuery(query); err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}

	path, err := mcpDBPath()
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("resolving database: %v", err)), nil
	}
	db, toolErr := openMCPReadOnlyStore(path)
	if toolErr != nil {
		return toolErr, nil
	}
	defer db.Close()

	queryCtx, cancel := bound.WithSQLQueryDeadline(ctx)
	defer cancel()

	conn, err := db.DB().Conn(queryCtx)
	if err != nil {
		return mcplib.NewToolResultError(mcpSQLQueryError(queryCtx, err)), nil
	}
	defer conn.Close()

	if _, err := sqlite.Limit(conn, sqlite3.SQLITE_LIMIT_LENGTH, mcpSQLMaxValueBytes); err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("setting SQL value length cap: %v", err)), nil
	}

	rows, err := conn.QueryContext(queryCtx, query)
	if err != nil {
		return mcplib.NewToolResultError(mcpSQLQueryError(queryCtx, err)), nil
	}
	defer rows.Close()

	cols, err := rows.Columns()
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("reading columns: %v", err)), nil
	}
	scan := bound.NewSQLScanState(cols)
	for rows.Next() {
		values := make([]any, len(cols))
		ptrs := make([]any, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			if mcpSQLValueTooBig(err) {
				return mcplib.NewToolResultError(mcpSQLQueryError(queryCtx, err)), nil
			}
			return mcplib.NewToolResultError(fmt.Sprintf("scanning row: %v", err)), nil
		}
		row := make(map[string]any)
		for i, col := range cols {
			row[col] = values[i]
		}
		if !scan.Add(row) {
			break
		}
	}
	// rows.Next() stops on a mid-iteration error without failing the loop, so
	// skipping rows.Err() would return a truncated result set as success.
	if err := rows.Err(); err != nil {
		return mcplib.NewToolResultError(mcpSQLQueryError(queryCtx, err)), nil
	}
	storeStatus, err := mcpStoreStatus(db)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("reading store status: %v", err)), nil
	}

	return toolResultJSON(mcpSQLEnvelope(scan.Rows, cols, storeStatus, scan.Truncated))
}

func mcpSQLEnvelope(rows []map[string]any, columns []string, storeStatus mcpStoreStatusKind, truncated bool) map[string]any {
	if rows == nil {
		rows = []map[string]any{}
	}
	out := map[string]any{
		"count":        len(rows),
		"columns":      columns,
		"rows":         rows,
		"store_status": storeStatus,
		"resumable":    false,
		"truncated":    truncated,
	}
	if truncated {
		out["returned_count"] = len(rows)
		out["max_bytes"] = bound.MaxBytes
		out["note"] = bound.SQLResultBoundNote
	}
	if storeStatus == mcpStoreStatusPartial {
		out["warning"] = "Local data may be incomplete because the latest sync attempt did not finish."
		out["next_step"] = mcpPartialStoreNextStep()
	} else if len(rows) == 0 && !truncated {
		if storeStatus == mcpStoreStatusEmpty {
			out["next_step"] = mcpEmptyStoreNextStep()
		} else {
			out["next_step"] = "The read-only SQL query returned no rows. Check resource_type filters, json_extract paths, or run cloro-pp-cli sync --resources states again if data may be stale."
		}
	}
	return out
}

func mcpSQLQueryError(queryCtx context.Context, err error) string {
	if queryCtx.Err() != nil {
		return fmt.Sprintf("query cancelled: %v. MCP SQL queries are bounded to %s; narrow the query with WHERE, GROUP BY, or an aggregate.", err, bound.SQLQueryTimeout)
	}
	if mcpSQLValueTooBig(err) {
		return fmt.Sprintf("query failed: a string or blob exceeds the MCP SQL value cap of %d bytes (4 MiB). Narrow the selected columns or use substr, json_extract, or length instead of returning oversized values.", mcpSQLMaxValueBytes)
	}
	msg := err.Error()
	if strings.Contains(strings.ToLower(msg), "no such table") {
		return fmt.Sprintf("query failed: %v. Synced records live in resources(resource_type, id, data), not one SQL table per resource. Filter by resource_type, for example resource_type='aimode', and read JSON fields with json_extract(data,'$.field').", err)
	}
	return fmt.Sprintf("query failed: %v", err)
}

func mcpSQLValueTooBig(err error) bool {
	var sqliteErr *sqlite.Error
	return errors.As(err, &sqliteErr) && sqliteErr.Code() == sqlite3.SQLITE_TOOBIG
}

// toolResultJSON renders v as the indented JSON body of an MCP text result,
// surfacing a marshal failure as a tool error instead of empty content.
func toolResultJSON(v any) (*mcplib.CallToolResult, error) {
	text, err := bound.JSON(v)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}
func registeredCommandMirrorCapabilities(s *server.MCPServer, capabilities []map[string]string) []map[string]string {
	registered := make([]map[string]string, 0, len(capabilities))
	root := cli.RootCmd()
	for _, capability := range capabilities {
		toolName := cobratree.ToolNameForCommand(s, root, capability["cli_command"])
		if toolName == "" {
			continue
		}
		entry := s.GetTool(toolName)
		if entry == nil || entry.Tool.Meta == nil || entry.Tool.Meta.AdditionalFields["pp:tenant-gate"] != "child-cli" {
			continue
		}
		capability["mcp_tool"] = toolName
		registered = append(registered, capability)
	}
	return registered
}

func handleContext(s *server.MCPServer) func(context.Context, mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return func(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
		return handleContextResult(s, ctx, req)
	}
}

